package com.example.HMS.service;

import com.example.HMS.dto.BillDto;
import com.example.HMS.dto.BillMapper;
import com.example.HMS.entity.Bill;
import com.example.HMS.repository.AppointmentRepository;
import com.example.HMS.repository.BillRepository;
import com.example.HMS.repository.PatientRepository;
import java.time.LocalDate;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.ArgumentCaptor;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

@ExtendWith(MockitoExtension.class)
class BillServiceTest {
    @Mock private BillRepository billRepository;
    @Mock private PatientRepository patientRepository;
    @Mock private AppointmentRepository appointmentRepository;
    @Mock private BillMapper billMapper;
    @InjectMocks private BillService billService;

    // GreyTest trace: createBill | hai liên kết tùy chọn đều null và hóa đơn được lưu, ánh xạ | BR-040, BR-041 -> TP-015 -> TC-244
    @Test
    void createBill_SavesAndMapsBillWithoutOptionalLinks() {
        // Arrange
        BillDto input = new BillDto();
        input.setAmount(125.5);
        input.setStatus(com.example.HMS.enums.PaymentStatus.PAID);
        input.setBillDate(LocalDate.of(2025, 3, 15));
        input.setPatientId(null);
        input.setAppointmentId(null);
        input.setPaymentMethod(com.example.HMS.enums.PaymentMethod.CARD);
        when(billRepository.save(any(Bill.class))).thenAnswer(invocation -> {
            Bill saved = invocation.getArgument(0);
            saved.setBillId(1001L);
            return saved;
        });

        // Act
        BillDto result = billService.createBill(input);

        // Assert
        ArgumentCaptor<Bill> captor = ArgumentCaptor.forClass(Bill.class);
        verify(billRepository).save(captor.capture());
        Bill saved = captor.getValue();
        assertEquals(1001L, saved.getBillId());
        assertEquals(125.5, saved.getAmount());
        assertEquals(com.example.HMS.enums.PaymentStatus.PAID, saved.getStatus());
        assertEquals(LocalDate.of(2025, 3, 15), saved.getBillDate());
        assertEquals(com.example.HMS.enums.PaymentMethod.CARD, saved.getPaymentMethod());
        assertNull(saved.getPatient());
        assertNull(saved.getAppointment());
        assertEquals(1001L, result.getBillId());
        assertEquals(125.5, result.getAmount());
        assertEquals(com.example.HMS.enums.PaymentStatus.PAID, result.getStatus());
        assertEquals(LocalDate.of(2025, 3, 15), result.getBillDate());
        assertEquals(com.example.HMS.enums.PaymentMethod.CARD, result.getPaymentMethod());
        assertNull(result.getPatientId());
        assertNull(result.getAppointmentId());
    }
}
